    bool isDownloading;
    List<string> modelFolders = new();

    protected override async Task OnInitializedAsync()
    {
        isDownloading = true;
        StateHasChanged();
        await Live2DDeskPet.EnsureDefaultModelsAsync();
        isDownloading = false;

        modelFolders = Directory.Exists(Live2DDeskPet.ModelRoot)
            ? Directory.GetDirectories(Live2DDeskPet.ModelRoot).Select(Path.GetFileName).Where(name => !string.IsNullOrEmpty(name)).ToList()!
            : new List<string>();

        // 确保当前配置值在可选范围内，否则回退到默认角色
        if (string.IsNullOrEmpty(Configuration.ModelName) || modelFolders.Contains(Configuration.ModelName) == false)
            Configuration.ModelName = modelFolders.Contains("Mao") ? "Mao" : modelFolders.FirstOrDefault() ?? "";

        StateHasChanged();
    }

    void OpenModelFolder()
    {
        Process.Start("explorer.exe", $"\"{Live2DDeskPet.ModelRoot}\"");
    }

    void ResetWindow()
    {
        Module?.ResetWindow();
    }

    // ==== 点击区域配置 UI 逻辑（结构化编辑） ====
    List<PetRegionConfig> regionEditorList = new();
    PetRegionConfig? foreverEditor;
    int regionSeq;
    List<Dictionary<string, object?>> settingsEditor = new();
    bool settingsLoaded;
    bool switching;

    /// <summary>当前菜单页：0=模型 1=区域 2=交互开关</summary>
    int tab;

    /// <summary>下拉选模型 → 立即真实切换（重载桌宠），不只是改配置值。</summary>
    async Task OnModelSelected(string name)
    {
        if (string.IsNullOrEmpty(name)) return;
        global::Alife.Foundation.AlifeLog.LogInformation($"[桌宠] 管理界面选择模型: {name}");
        Configuration.ModelName = name;
        switching = true;
        StateHasChanged();
        try { if (Module is not null) await Module.SwitchModelAsync(name); }
        catch { }
        switching = false;
        StateHasChanged();
    }

    void LoadRegionsIntoEditor()
    {
        // 只在编辑器为空时从 storage 读取一次（避免覆盖用户在编辑器里未保存的修改）
        if (regionEditorList.Count > 0) return;
        regionEditorList = Module?.GetRegions() ?? new List<PetRegionConfig>();
    }

    string regionMsg = "";

    static string ShapeName(PetRegionShape s) => s switch
    {
        PetRegionShape.Ellipse => "椭圆",
        PetRegionShape.Polygon => "多边形",
        _ => "矩形",
    };

    static string GestureVerb(string kind) => kind switch
    {
        "dblclick" => "双击",
        "longpress" => "长按",
        "stroke" => "来回抚摸",
        _ => "用滚轮戳",
    };

    static string GestureSummary(PetRegionConfig r)
    {
        var on = new List<string>();
        if (r.DblclickOn) on.Add("双击");
        if (r.LongpressOn) on.Add("长按");
        if (r.StrokeOn) on.Add("抚摸");
        if (r.WheelOn) on.Add("滚轮");
        return on.Count == 0 ? " · 无手势" : " · " + string.Join("/", on);
    }

    static string GetS(Dictionary<string, object?> d, string key)
        => d.TryGetValue(key, out object? v) && v != null ? (v.ToString() ?? "") : "";

    static string[] GetArr(Dictionary<string, object?> d, string key)
        => d.TryGetValue(key, out object? v) && v is string[] a ? a : Array.Empty<string>();

    void Button(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, string text, string? cls, Action onClick)
    {
        b.OpenElement(regionSeq++, "button");
        b.AddAttribute(regionSeq++, "type", "button");
        b.AddAttribute(regionSeq++, "class", string.IsNullOrEmpty(cls) ? "alf-btn" : "alf-btn alf-btn-" + cls);
        b.AddAttribute(regionSeq++, "onclick", EventCallback.Factory.Create(this, (global::Microsoft.AspNetCore.Components.Web.MouseEventArgs e) => { onClick(); StateHasChanged(); }));
        b.AddContent(regionSeq++, text);
        b.CloseElement();
    }

    void AddShapeSelect(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, PetRegionConfig region)
    {
        b.AddContent(regionSeq++, "形状 ");
        b.OpenElement(regionSeq++, "select");
        b.AddAttribute(regionSeq++, "style", "padding:2px 4px;");
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e =>
        {
            region.Shape = (e.Value?.ToString()) switch
            {
                "Ellipse" => PetRegionShape.Ellipse,
                "Polygon" => PetRegionShape.Polygon,
                _ => PetRegionShape.Rect,
            };
        }));
        foreach (PetRegionShape s in new[] { PetRegionShape.Rect, PetRegionShape.Ellipse, PetRegionShape.Polygon })
        {
            b.OpenElement(regionSeq++, "option");
            b.AddAttribute(regionSeq++, "value", s.ToString());
            if (region.Shape == s) b.AddAttribute(regionSeq++, "selected", true);
            b.AddContent(regionSeq++, ShapeName(s));
            b.CloseElement();
        }
        b.CloseElement();
    }

    void RenderGestureRows(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, PetRegionConfig region)
    {
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "margin-top:8px; font-size:13px;");
        b.AddContent(regionSeq++, "手势反应（勾选才生效；话术留空用默认模板）：");
        foreach (string kind in new[] { "dblclick", "longpress", "stroke", "wheel" })
            RenderGestureRow(b, region, kind);
        b.CloseElement();
    }

    void RenderGestureRow(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, PetRegionConfig region, string kind)
    {
        bool on = kind switch { "dblclick" => region.DblclickOn, "longpress" => region.LongpressOn, "stroke" => region.StrokeOn, _ => region.WheelOn };
        string msg = kind switch { "dblclick" => region.DblclickMsg, "longpress" => region.LongpressMsg, "stroke" => region.StrokeMsg, _ => region.WheelMsg };
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "display:flex; gap:6px; align-items:center; margin-top:4px;");
        b.OpenElement(regionSeq++, "input");
        b.AddAttribute(regionSeq++, "type", "checkbox");
        if (on) b.AddAttribute(regionSeq++, "checked", true);
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e =>
        {
            bool v = e.Value is bool bv && bv;
            switch (kind)
            {
                case "dblclick": region.DblclickOn = v; break;
                case "longpress": region.LongpressOn = v; break;
                case "stroke": region.StrokeOn = v; break;
                default: region.WheelOn = v; break;
            }
        }));
        b.CloseElement();
        b.AddContent(regionSeq++, GestureVerb(kind));
        b.OpenElement(regionSeq++, "input");
        b.AddAttribute(regionSeq++, "type", "text");
        b.AddAttribute(regionSeq++, "value", msg);
        b.AddAttribute(regionSeq++, "placeholder", "默认：" + RegionInteractionModule.DefaultText("", region.Name, GestureVerb(kind)));
        b.AddAttribute(regionSeq++, "style", "flex:1; min-width:180px;");
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e =>
        {
            string v = e.Value?.ToString() ?? "";
            switch (kind)
            {
                case "dblclick": region.DblclickMsg = v; break;
                case "longpress": region.LongpressMsg = v; break;
                case "stroke": region.StrokeMsg = v; break;
                default: region.WheelMsg = v; break;
            }
        }));
        b.CloseElement();
        b.CloseElement();
    }

    /// <summary>交互总开关：与桌宠窗口内设置面板共用同一份数据（PetInteractionHub）。</summary>
    void RenderSettingsEditor(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b)
    {
        if (!settingsLoaded)
        {
            settingsEditor = Module?.GetPetSettings() ?? new List<Dictionary<string, object?>>();
            settingsLoaded = true;
        }
        if (settingsEditor.Count == 0)
        {
            b.OpenElement(regionSeq++, "div");
            b.AddAttribute(regionSeq++, "style", "font-size:13px; color:#999;");
            b.AddContent(regionSeq++, "（桌宠还没启动，稍后回到本页可见）");
            b.CloseElement();
            return;
        }
        string lastGroup = "\u0000";
        foreach (Dictionary<string, object?> it in settingsEditor)
        {
            string group = GetS(it, "group");
            if (group != lastGroup)
            {
                lastGroup = group;
                b.OpenElement(regionSeq++, "div");
                b.AddAttribute(regionSeq++, "style", "margin-top:8px; font-size:12px; color:#1677ff;");
                b.AddContent(regionSeq++, group);
                b.CloseElement();
            }
            string key = GetS(it, "key");
            string label = GetS(it, "label");
            string type = GetS(it, "type");
            string value = GetS(it, "value");
            Dictionary<string, object?> captured = it;

            b.OpenElement(regionSeq++, "div");
            b.AddAttribute(regionSeq++, "style", "display:flex; gap:8px; align-items:center; margin-top:4px; font-size:13px;");

            if (type == "bool")
            {
                b.OpenElement(regionSeq++, "input");
                b.AddAttribute(regionSeq++, "type", "checkbox");
                if (value == "1") b.AddAttribute(regionSeq++, "checked", true);
                b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e =>
                {
                    string v = (e.Value is bool bv && bv) ? "1" : "0";
                    Module?.SetPetSetting(key, v);
                    captured["value"] = v;
                }));
                b.CloseElement();
                b.AddContent(regionSeq++, label);
            }
            else if (type == "choice")
            {
                b.AddContent(regionSeq++, label + " ");
                string[] opts = GetArr(it, "options");
                string[] labels = GetArr(it, "optionLabels");
                b.OpenElement(regionSeq++, "select");
                b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e =>
                {
                    string v = e.Value?.ToString() ?? "";
                    Module?.SetPetSetting(key, v);
                    captured["value"] = v;
                }));
                for (int i = 0; i < opts.Length; i++)
                {
                    b.OpenElement(regionSeq++, "option");
                    b.AddAttribute(regionSeq++, "value", opts[i]);
                    if (opts[i] == value) b.AddAttribute(regionSeq++, "selected", true);
                    b.AddContent(regionSeq++, i < labels.Length ? labels[i] : opts[i]);
                    b.CloseElement();
                }
                b.CloseElement();
            }
            else
            {
                b.AddContent(regionSeq++, label + " ");
                b.OpenElement(regionSeq++, "input");
                b.AddAttribute(regionSeq++, "type", "text");
                b.AddAttribute(regionSeq++, "value", value);
                b.AddAttribute(regionSeq++, "style", "width:110px;");
                b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e =>
                {
                    string v = e.Value?.ToString() ?? "";
                    Module?.SetPetSetting(key, v);
                    captured["value"] = v;
                }));
                b.CloseElement();
            }

            b.CloseElement();
        }
    }

    // ==== 模型自带 Interaction 交互池编辑 ====
    List<Dictionary<string, object?>> ixEditor = new();
    readonly Dictionary<string, string> ixEnabled = new();
    bool ixLoaded;
    string ixMsg = "";

    void LoadInteractionEditor()
    {
        if (ixLoaded) return;
        ixEditor = Module?.GetModelInteractionEditor() ?? new List<Dictionary<string, object?>>();
        ixEnabled.Clear();
        foreach (Dictionary<string, object?> s in Module?.GetPetSettings() ?? new List<Dictionary<string, object?>>())
        {
            string k = GetS(s, "key");
            if (k.StartsWith("ix_", StringComparison.Ordinal)) ixEnabled[k] = GetS(s, "value");
        }
        ixLoaded = true;
    }

    static List<Dictionary<string, object?>> EntriesOf(Dictionary<string, object?> t)
        => t.TryGetValue("entries", out object? v) && v is List<Dictionary<string, object?>> l
            ? l : new List<Dictionary<string, object?>>();

    void SaveInteractionEditor()
    {
        var pools = new Dictionary<string, List<ModelInteractionEntry>>();
        foreach (Dictionary<string, object?> t in ixEditor)
        {
            List<ModelInteractionEntry> list = new();
            foreach (Dictionary<string, object?> e in EntriesOf(t))
                list.Add(new ModelInteractionEntry(GetS(e, "text"), GetS(e, "exp"), GetS(e, "mtn")));
            pools[GetS(t, "type")] = list;
        }
        string err = Module?.SaveModelInteractions(pools) ?? "模块未就绪";
        ixMsg = string.IsNullOrEmpty(err) ? "已写入模型文件（原文件已备份为 .bak），并立即生效" : err;
    }

    void AddOptionSelect(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, string label, string[] options, string value, Action<string> setter)
    {
        b.AddContent(regionSeq++, label + " ");
        b.OpenElement(regionSeq++, "select");
        b.AddAttribute(regionSeq++, "style", "max-width:130px;");
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e => setter(e.Value?.ToString() ?? "")));
        b.OpenElement(regionSeq++, "option");
        b.AddAttribute(regionSeq++, "value", "");
        if (string.IsNullOrEmpty(value)) b.AddAttribute(regionSeq++, "selected", true);
        b.AddContent(regionSeq++, "（无）");
        b.CloseElement();
        foreach (string o in options)
        {
            b.OpenElement(regionSeq++, "option");
            b.AddAttribute(regionSeq++, "value", o);
            if (o == value) b.AddAttribute(regionSeq++, "selected", true);
            b.AddContent(regionSeq++, o);
            b.CloseElement();
        }
        b.CloseElement();
    }

    void RenderInteractionEntryRow(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, List<Dictionary<string, object?>> entries, int index, string[] exps, string[] mtns)
    {
        Dictionary<string, object?> e = entries[index];
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "display:flex; gap:6px; align-items:center; flex-wrap:wrap; margin-top:4px; font-size:13px;");

        b.OpenElement(regionSeq++, "input");
        b.AddAttribute(regionSeq++, "type", "text");
        b.AddAttribute(regionSeq++, "value", GetS(e, "text"));
        b.AddAttribute(regionSeq++, "placeholder", "气泡文本");
        b.AddAttribute(regionSeq++, "style", "flex:1; min-width:200px;");
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, ev => e["text"] = ev.Value?.ToString() ?? ""));
        b.CloseElement();

        AddOptionSelect(b, "表情", exps, GetS(e, "exp"), v => e["exp"] = v);
        AddOptionSelect(b, "动作", mtns, GetS(e, "mtn"), v => e["mtn"] = v);

        int captured = index;
        Button(b, "删", "danger", () => entries.RemoveAt(captured));

        b.CloseElement();
    }

    void RenderModelInteractionEditor(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b)
    {
        LoadInteractionEditor();
        if (ixEditor.Count == 0)
        {
            b.OpenElement(regionSeq++, "div");
            b.AddAttribute(regionSeq++, "style", "font-size:13px; color:#999;");
