        Button(b, "保存到模型文件", "primary", SaveInteractionEditor);
        if (!string.IsNullOrEmpty(ixMsg))
        {
            b.OpenElement(regionSeq++, "span");
            b.AddAttribute(regionSeq++, "style", "font-size:12px; color:#52c41a;");
            b.AddContent(regionSeq++, ixMsg);
            b.CloseElement();
        }
        b.CloseElement();

        foreach (Dictionary<string, object?> t in ixEditor)
        {
            string label = GetS(t, "label");
            string type = GetS(t, "type");
            List<Dictionary<string, object?>> entries = EntriesOf(t);

            b.OpenElement(regionSeq++, "details");
            b.AddAttribute(regionSeq++, "style", "border:1px solid #e0e0e0; border-radius:8px; margin-bottom:8px; padding:6px 10px; background:#fafafa;");
            b.AddAttribute(regionSeq++, "open", true);
            b.OpenElement(regionSeq++, "summary");
            b.AddContent(regionSeq++, $"{label}（{type}）· {entries.Count} 条");
            b.CloseElement();

            string ixKey = GetS(t, "key");
            b.OpenElement(regionSeq++, "div");
            b.AddAttribute(regionSeq++, "style", "margin-top:6px; display:flex; align-items:center; gap:6px; font-size:13px;");
            b.OpenElement(regionSeq++, "input");
            b.AddAttribute(regionSeq++, "type", "checkbox");
            if (ixEnabled.TryGetValue(ixKey, out string? en) && en == "1") b.AddAttribute(regionSeq++, "checked", true);
            b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e =>
            {
                string v = (e.Value is bool bb && bb) ? "1" : "0";
                ixEnabled[ixKey] = v;
                Module?.SetPetSetting(ixKey, v);
            }));
            b.CloseElement();
            b.AddContent(regionSeq++, "启用该交互（关掉就不触发这一类）");
            b.CloseElement();

            for (int i = 0; i < entries.Count; i++)
                RenderInteractionEntryRow(b, entries, i, exps, mtns);

            Button(b, "+ 添加一条", null, () =>
                entries.Add(new Dictionary<string, object?> { ["text"] = "", ["exp"] = "", ["mtn"] = "" }));

            b.CloseElement();
        }
    }


    void RenderRegionEditor(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b)
    {
        if (regionEditorList.Count == 0)
            LoadRegionsIntoEditor();

        // 顶部：添加区域 + 保存 + 重新载入
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px;");
        Button(b, "+ 添加区域", null, () =>
            regionEditorList.Add(new PetRegionConfig { Name = "新区域", X1 = -100, Y1 = -100, X2 = 100, Y2 = 100, DblclickOn = true, Taps = new List<PetRegionTap> { new() { Times = 1 } } }));
        Button(b, "保存区域配置", "primary", () => { Module?.SaveRegions(regionEditorList); regionMsg = "已保存 " + DateTime.Now.ToString("HH:mm:ss"); });
        if (!string.IsNullOrEmpty(regionMsg))
        {
            b.OpenElement(regionSeq++, "span");
            b.AddAttribute(regionSeq++, "style", "font-size:12px; color:#52c41a; align-self:center;");
            b.AddContent(regionSeq++, regionMsg);
            b.CloseElement();
        }
        b.CloseElement();

        // 区域列表
        for (int i = 0; i < regionEditorList.Count; i++)
        {
            RenderRegionCard(b, regionEditorList[i], i);
        }

        // 永久不穿透区（不可删除，仅一个）
        RenderForeverEditor(b);
    }

    void RenderForeverEditor(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b)
    {
        if (foreverEditor == null)
        {
            foreverEditor = Module?.GetForeverRegion() ?? new PetRegionConfig { Name = "永久区", X1 = -100, Y1 = -100, X2 = 100, Y2 = 100 };
        }
        b.OpenElement(regionSeq++, "details");
        b.AddAttribute(regionSeq++, "style", "border:1px solid #aaa; border-radius:8px; margin-top:12px; padding:6px 10px; background:#f5f5f5;");
        b.AddAttribute(regionSeq++, "open", true);
        b.OpenElement(regionSeq++, "summary");
        b.AddContent(regionSeq++, $"永久不穿透区（{foreverEditor.Name}）— 拖动带动桌宠，双击切换穿透状态");
        b.CloseElement();

        // 坐标 + 形状（不可删除，只有位置大小）
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "margin-top:6px; display:flex; gap:10px; flex-wrap:wrap; align-items:center;");
        // 所见即所得：显示当前窗口真实坐标，保存时换算回模型单位（区域存储空间）
        AddShapeSelect(b, foreverEditor!);
        AddCoordInput(b, "上 Y1", Module?.RegionToWindowY(foreverEditor.Y1) ?? foreverEditor.Y1, v => foreverEditor.Y1 = Module?.WindowToRegionY(v) ?? v);
        AddCoordInput(b, "下 Y2", Module?.RegionToWindowY(foreverEditor.Y2) ?? foreverEditor.Y2, v => foreverEditor.Y2 = Module?.WindowToRegionY(v) ?? v);
        AddCoordInput(b, "左 X1", Module?.RegionToWindowX(foreverEditor.X1) ?? foreverEditor.X1, v => foreverEditor.X1 = Module?.WindowToRegionX(v) ?? v);
        AddCoordInput(b, "右 X2", Module?.RegionToWindowX(foreverEditor.X2) ?? foreverEditor.X2, v => foreverEditor.X2 = Module?.WindowToRegionX(v) ?? v);
        b.CloseElement();

        RenderGestureRows(b, foreverEditor!);

        // 保存永久区
        Button(b, "保存永久区", "primary", () => Module?.SaveForeverRegion(foreverEditor!));
        b.CloseElement();
    }

    void RenderRegionCard(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, PetRegionConfig region, int index)
    {
        b.OpenElement(regionSeq++, "details");
        b.AddAttribute(regionSeq++, "style", "border:1px solid #e0e0e0; border-radius:8px; margin-bottom:8px; padding:6px 10px; background:#fafafa;");
        b.AddAttribute(regionSeq++, "open", true);
        b.OpenElement(regionSeq++, "summary");
        b.AddContent(regionSeq++, $"区域 {index + 1}：{region.Name}（{ShapeName(region.Shape)}{GestureSummary(region)}）");
        b.CloseElement();

        // 名称
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "margin-top:6px;");
        b.AddContent(regionSeq++, "名称 ");
        b.OpenElement(regionSeq++, "input");
        b.AddAttribute(regionSeq++, "type", "text");
        b.AddAttribute(regionSeq++, "value", region.Name);
        b.AddAttribute(regionSeq++, "style", "width:200px;");
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e => region.Name = e.Value?.ToString() ?? ""));
        b.CloseElement();
        b.CloseElement();

        // 形状 + 坐标：上下合并（Y1上 Y2下）+ 左右合并（X1左 X2右）
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "margin-top:6px; display:flex; gap:10px; flex-wrap:wrap; align-items:center;");
        AddShapeSelect(b, region);
        // 所见即所得：显示当前窗口真实坐标，保存时换算回模型单位（区域存储空间）
        AddCoordInput(b, "上 Y1", Module?.RegionToWindowY(region.Y1) ?? region.Y1, v => region.Y1 = Module?.WindowToRegionY(v) ?? v);
        AddCoordInput(b, "下 Y2", Module?.RegionToWindowY(region.Y2) ?? region.Y2, v => region.Y2 = Module?.WindowToRegionY(v) ?? v);
        AddCoordInput(b, "左 X1", Module?.RegionToWindowX(region.X1) ?? region.X1, v => region.X1 = Module?.WindowToRegionX(v) ?? v);
        AddCoordInput(b, "右 X2", Module?.RegionToWindowX(region.X2) ?? region.X2, v => region.X2 = Module?.WindowToRegionX(v) ?? v);
        b.CloseElement();
        if (region.Shape == PetRegionShape.Polygon)
        {
            b.OpenElement(regionSeq++, "div");
            b.AddAttribute(regionSeq++, "style", "margin-top:4px; font-size:12px; color:#888;");
            b.AddContent(regionSeq++, $"多边形顶点 {region.Points.Count / 2} 个：顶点形状在桌宠窗口的编辑模式里拖画/调整，这里只改属性与话术。");
            b.CloseElement();
        }

        // 档位列表
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "margin-top:8px;");
        b.AddContent(regionSeq++, "连点档位：");
        for (int t = 0; t < region.Taps.Count; t++)
            RenderTapRow(b, region, t);
        b.OpenElement(regionSeq++, "button");
        b.AddAttribute(regionSeq++, "type", "button");
        b.AddAttribute(regionSeq++, "style", "margin-top:4px; padding:2px 10px; cursor:pointer; font-size:12px;");
        b.AddAttribute(regionSeq++, "onclick", EventCallback.Factory.Create(this, (global::Microsoft.AspNetCore.Components.Web.MouseEventArgs e) => {
            region.Taps.Add(new PetRegionTap { Times = region.Taps.Count + 1 });
            StateHasChanged();
        }));
        b.AddContent(regionSeq++, "+ 添加档位");
        b.CloseElement();
        b.CloseElement();

        // 手势反应（与该区域在桌宠窗口内的配置是同一份数据）
        RenderGestureRows(b, region);

        // 删除区域
        Button(b, "删除此区域", "danger", () => regionEditorList.RemoveAt(index));

        b.CloseElement(); // details
    }

    void AddCoordInput(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, string label, double value, Action<double> setter)
    {
        b.AddContent(regionSeq++, label + " ");
        b.OpenElement(regionSeq++, "input");
        b.AddAttribute(regionSeq++, "type", "number");
        b.AddAttribute(regionSeq++, "value", value.ToString(System.Globalization.CultureInfo.InvariantCulture));
        b.AddAttribute(regionSeq++, "style", "width:70px;");
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e =>
        {
            if (double.TryParse(e.Value?.ToString(), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double d)) setter(d);
        }));
        b.CloseElement();
    }

    void RenderTapRow(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, PetRegionConfig region, int tapIndex)
    {
        PetRegionTap tap = region.Taps[tapIndex];
        b.OpenElement(regionSeq++, "div");
        b.AddAttribute(regionSeq++, "style", "display:flex; gap:6px; flex-wrap:wrap; align-items:center; margin-top:4px;");
        b.AddContent(regionSeq++, "点");
        b.OpenElement(regionSeq++, "input");
        b.AddAttribute(regionSeq++, "type", "number");
        b.AddAttribute(regionSeq++, "value", tap.Times.ToString());
        b.AddAttribute(regionSeq++, "style", "width:50px;");
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e => { if (int.TryParse(e.Value?.ToString(), out int d)) tap.Times = d; }));
        b.CloseElement();
        b.AddContent(regionSeq++, "次");
        AddTapField(b, "发给阿宵的消息", tap.Message ?? "", v => tap.Message = v ?? "", 260);
        b.OpenElement(regionSeq++, "button");
        b.AddAttribute(regionSeq++, "type", "button");
        b.AddAttribute(regionSeq++, "style", "padding:0 8px; cursor:pointer; color:#d33; font-size:12px;");
        b.AddAttribute(regionSeq++, "onclick", EventCallback.Factory.Create(this, (global::Microsoft.AspNetCore.Components.Web.MouseEventArgs e) => {
            region.Taps.RemoveAt(tapIndex);
            StateHasChanged();
        }));
        b.AddContent(regionSeq++, "删");
        b.CloseElement();
        b.CloseElement();
    }

    void AddTapField(global::Microsoft.AspNetCore.Components.Rendering.RenderTreeBuilder b, string label, string value, Action<string> setter, int width)
    {
        b.AddContent(regionSeq++, label + " ");
        b.OpenElement(regionSeq++, "input");
        b.AddAttribute(regionSeq++, "type", "text");
        b.AddAttribute(regionSeq++, "value", value);
        b.AddAttribute(regionSeq++, "style", $"width:{width}px;");
        b.AddAttribute(regionSeq++, "onchange", EventCallback.Factory.Create<global::Microsoft.AspNetCore.Components.ChangeEventArgs>(this, e => setter(e.Value?.ToString())));
        b.CloseElement();
    }

